export async function administratorPermission(
  signedIn: boolean,
  readSession: () => Promise<{ data?: { administrator?: unknown } }>
): Promise<boolean> {
  if (!signedIn) return false;
  try {
    const response = await readSession();
    return response.data?.administrator === true;
  } catch {
    return false;
  }
}

.tcAdminActions { display: flex; flex-wrap: wrap; gap: 12px; margin: 20px 0; }
.tcAdminActions button, .tcAdminShortcut { min-height: 44px; padding: 10px 16px; border: 1px solid #b8c9c2; border-radius: 12px; background: #fff; color: #06231c; font: inherit; font-size: 14px; font-weight: 650; cursor: pointer; }
.tcAdminActions button:first-child, .tcAdminShortcut { background: #06231c; color: #fff; }
.tcAdminActions button:disabled, .tcAdminShortcut:disabled { opacity: .6; cursor: wait; }
.tcAdminActions button:focus-visible, .tcAdminShortcut:focus-visible { outline: 3px solid #66a80f; outline-offset: 3px; }
.tcAdminAccess p { overflow-wrap: anywhere; }
@media (max-width: 600px) { .tcAdminActions { flex-direction: column; } .tcAdminActions button { width: 100%; } .tcAdminShortcut { padding: 8px 10px; font-size: 12px; } }
